    internal static class MetaTransformScriptModelXmlSerializer
    {
        private static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

        internal static MetaTransformScriptModel Load(string workspacePath, bool searchUpward)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(workspacePath);
            if (searchUpward)
            {
                throw new NotSupportedException("Typed workspace loading does not search parent directories. Pass an explicit workspace path.");
            }

            if (HasRuntimeExtendedShape())
            {
                return TypedWorkspaceXmlSerializer.Load<MetaTransformScriptModel>(workspacePath, searchUpward);
            }

            var workspaceRootPath = TypedWorkspaceXmlSerializer.RequireWorkspace<MetaTransformScriptModel>(workspacePath);

            var model = new MetaTransformScriptModel();
            var loadState = new LoadState();
            var relationshipBuffers = new RelationshipBuffers();
            var instanceDirectoryPath = TypedWorkspaceXmlSerializer.ResolveInstanceDirectoryPath(workspaceRootPath);
            if (!Directory.Exists(instanceDirectoryPath))
            {
                return model;
            }

            foreach (var shardPath in Directory.GetFiles(instanceDirectoryPath, "*.xml")
                         .OrderBy(Path.GetFileName, StringComparer.OrdinalIgnoreCase)
                         .ThenBy(path => path, StringComparer.Ordinal))
            {
                LoadShard(model, shardPath, loadState, relationshipBuffers);
            }

            var loadIndexes = new LoadIndexes(model);
            ResolveRelationshipGroup1(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup2(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup3(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup4(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup5(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup6(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup7(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup8(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup9(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup10(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup11(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup12(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup13(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup14(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup15(loadIndexes, relationshipBuffers);
            ResolveRelationshipGroup16(loadIndexes, relationshipBuffers);
            return model;
        }

        internal static void Save(MetaTransformScriptModel model, string workspacePath)
        {
            ArgumentNullException.ThrowIfNull(model);
            ArgumentException.ThrowIfNullOrWhiteSpace(workspacePath);
            if (HasRuntimeExtendedShape())
            {
                TypedWorkspaceXmlSerializer.Save(model, workspacePath);
                return;
            }

            TypedWorkspaceXmlSerializer.SaveModel(model, workspacePath);

            var saveIndexes = new SaveIndexes(model);

            var workspaceRootPath = Path.GetFullPath(workspacePath);
            var instanceDirectoryPath = TypedWorkspaceXmlSerializer.ResolveInstanceDirectoryPath(workspaceRootPath);
            Directory.CreateDirectory(instanceDirectoryPath);
            var expectedShardPaths = BuildExpectedShardPaths(instanceDirectoryPath);
            SaveShardGroup1(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup2(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup3(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup4(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup5(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup6(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup7(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup8(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup9(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup10(model, instanceDirectoryPath, saveIndexes);
            SaveShardGroup11(model, instanceDirectoryPath, saveIndexes);
            foreach (var shardPath in Directory.GetFiles(instanceDirectoryPath, "*.xml")
                         .OrderBy(Path.GetFileName, StringComparer.OrdinalIgnoreCase)
                         .ThenBy(path => path, StringComparer.Ordinal))
            {
                if (!expectedShardPaths.Contains(Path.GetFullPath(shardPath)))
                {
                    File.Delete(shardPath);
                }
            }
        }

