        private static void LoadShard(MetaTransformScriptModel model, string shardPath, LoadState loadState, RelationshipBuffers relationshipBuffers)
        {
            using var reader = XmlReader.Create(shardPath, new XmlReaderSettings
            {
                IgnoreComments = true,
                IgnoreWhitespace = true,
            });
            reader.MoveToContent();
            if (reader.NodeType != XmlNodeType.Element || !string.Equals(reader.LocalName, "MetaTransformScript", StringComparison.Ordinal))
            {
                throw new InvalidDataException($"Instance XML '{shardPath}' root must be <MetaTransformScript>.");
            }
            if (reader.IsEmptyElement)
            {
                reader.Read();
                return;
            }
            reader.ReadStartElement("MetaTransformScript");
            while (reader.NodeType == XmlNodeType.Element)
            {
                switch (reader.LocalName)
                {
                    case "AtTimeZoneCallList":
                        LoadAtTimeZoneCallList(model, reader, loadState, relationshipBuffers);
                        break;
                    case "AtTimeZoneCallDateValueLinkList":
                        LoadAtTimeZoneCallDateValueLinkList(model, reader, loadState, relationshipBuffers);
                        break;
                    case "AtTimeZoneCallTimeZoneLinkList":
                        LoadAtTimeZoneCallTimeZoneLinkList(model, reader, loadState, relationshipBuffers);
                        break;
                    case "BinaryExpressionList":
                        LoadBinaryExpressionList(model, reader, loadState, relationshipBuffers);
